      "xr": "Как и мехи GMS, оружие GMS — надёжный галактический стандарт: сделано из взаимозаменяемых деталей и выдерживает почти любые условия. Сейчас выпускаются три линейки.\nЛинейка Type-I (T-1) — это мощное, надёжное и обычное кинетическое оружие дальнего и ближнего боя, включая штурмовую винтовку GMS, тяжёлый пулемёт, дробовик, пистолет и различные лёгкие и тяжёлые клинки. Как надёжный галактический стандарт, линейка T-1 — самая распространённая линейка оружия мех-масштаба во всей галактике. В духе конструкторских заметок «Эвереста» оружие T-1 просто устроено, с малым числом движущихся частей (если они вообще есть), и рассчитано на использование в любой среде или адаптацию к ней.",
      "gr": "Надёжное 2",
