      "rr": "Угроза 1",
      "xr": "Как и мехи GMS, оружие GMS — надёжный галактический стандарт: сделано из взаимозаменяемых деталей и выдерживает почти любые условия. Сейчас выпускаются три линейки.\nЛинейка Type-II (T-2) — это фирменное «заряженное» оружие ближнего боя и энергетическое оружие GMS. Заряженное оружие ближнего боя T-2 конструктивно похоже на оружие ближнего боя T-1, но сделано из других материалов, чтобы выдерживать сильный жар проецируемых плазменных оболочек. Эти оболочки можно включать и выключать по необходимости пилота. Энергетическое оружие T-2 от GMS, как и кинетика T-1, — это крепкие инструменты с предсказуемым ростом мощности, минимальным рассеиванием частиц и стабильными характеристиками. У них универсальные порты, позволяющие подключать различные источники питания — от жёстких кабельных подключений до энергоблоков «магазинного» типа.",
