      "xr": "Как и мехи GMS, оружие GMS — надёжный галактический стандарт: сделано из взаимозаменяемых деталей и выдерживает почти любые условия. Сейчас выпускаются три линейки.\nЛинейка Type-III (T-3) состоит из тяжёлого оружия, боеприпасов и другого экзотического, специализированного или массивного оружия. В эту широкую категорию входят обычные кинетические противоматериальные винтовки, сверхскорострельные импульсные винтовки, ракетные установки, пушки и дрон-нексусы — пусковые установки типа «улей», служащие миниатюрными фабрикой, ангаром и системой развёртывания переносных дронов. В эту категорию также входит грозный «сегментный нож» — система, использующая мгновенную печать для создания одноразового клинкового оружия вблизи пользователя.",
      "gr": "Дуговое, Неточное",
      "labr": "GMS · LL0 · Main",
      "lic": "GMS",
      "ll": 0,
      "lim": 0,
      "x": "Much like GMS mechs, GMS weapons are reliable galactic standards, made using interchangeable parts and built to withstand almost any conditions. There are three lines currently in production.\nThe Type-III (T-3) line is made up of heavy weapons, ordnance, and other exotic, specialized, or massive weapons. A broad classification, the T-3 range includes conventional-kinetic anti-materiel rifles, super-rapid cycling pulse rifles, missile racks, cannons, and drone nexuses – “hive”style launchers that serve as miniature factory, hangar, and deployment systems for portable drones. The classification also includes the fearsome “segment knife”, a system that uses flash-printing to produce disposable edged weapons in a vicinity around the user."
