      "xr": "Профиль — Стандартный: 1d6 кинетический; Дальность 8; в отличие от другого сверхтяжёлого оружия, «Левиафан» можно использовать в Скирмише. Вы можете раскрутить стволы этого оружия быстрым действием.; Раскрутка «Левиафана» (быстрое): Раскрутите стволы тяжёлой штурмовой пушки «Левиафан», замедлив свой мех и получив возможность использовать профиль «Режим раскрутки».\n\nПрофиль — Режим раскрутки: 4d6+4 кинетический; Дальность 8; теги: Надёжное 5, Тепло 2 (себе); пока стволы раскручены, вы Замедлены и больше не можете использовать «Левиафан» в Скирмише.\nЭтот эффект можно завершить протоколом.; Остановка раскрутки (протокол): Завершите «Режим раскрутки» тяжёлой штурмовой пушки «Левиафан», сняв состояние «Замедленный» и вернув «Левиафану» возможность использовать профиль «Стандартный».\n\nТяжёлая штурмовая пушка «Левиафан» (ТШП) — это массивная многоствольная роторная пушка с питанием из внешнего резервуара, обычно устанавливаемая на спину несущего её шасси. В немодифицированном виде «Левиафан» следует стрелять только в пределах рекомендованных интервалов очереди, чтобы не допустить ударной травмы суставов и пилота.\nСовместно с Think Tank от Harrison Armory компания IPS-N сейчас исследует дистанционные решения проблемы расхода боеприпасов этой пушки.",
