      "ll": 3,
      "lim": 0,
      "x": "Profile — Standard: 1d6 Kinetic; Range 8; Unlike other Superheavy weapons, the Leviathan can be used with Skirmish. You can spin up this weapon’s barrels as a quick action.; Spin Up Leviathan (Quick): Spin up the barrels of the Leviathan Heavy Assault Cannon, Slowing your mech and allowing use of its \"Spin-Up Mode\" profile.\n\nProfile — Spin-Up Mode: 4d6+4 Kinetic; Range 8; tags: Reliable 5, Heat 2 (Self); While spinning, you are Slowed and can no longer use the Leviathan with Skirmish.\nYou can cease this effect as a protocol.; Cease Spin-Up (Protocol): End the Leviathan Heavy Assault Cannon's \"Spin-Up Mode\", ending the Slowed condition and allowing the Leviathan to be used with its \"Standard\" profile.\n\nThe Leviathan Heavy Assault Cannon (HAC) is a massive, multi-barrel rotary cannon fed by an external reservoir, usually dorsally mounted on the chassis carrying it. Unmodified, the Leviathan should only be fired within the recommended burst timing specifications to prevent percussive trauma to joints and pilots.\nIn partnership with Harrison Armory’s Think Tank, IPS-N is currently investigating remote solutions for the cannon’s ammunition consumption demands."
