      "rr": "Угроза 1",
      "xr": "Это оружие наносит 10 энергетического урона AP объектам, укрытиям, местности и окружению.\n\nПлазменные резаки сначала были инструментами: простыми клинками, способными включать и поддерживать плазменную оболочку, чтобы легче резать металл. Неоднократное импровизированное использование резаков как оружия личной защиты против пиратских абордажных групп убедило IPS-N в необходимости военной версии гражданского инструмента — «Каттера», теперь уже второго поколения. «Каттер» MkII питается напрямую от энергоядра меха, с портом для подключения энергоблоков на случай обрыва кабеля. Хотя режущую кромку можно укоротить до длины ножа, самая популярная настройка — «абордажная сабля»: вариант средней длины, идеально сочетающий дальность и манёвренность в ближнем бою.",
      "gr": "Тепло 1 (себе)",
      "labr": "IPS-N · Ланкастер · LL3 · Aux",
      "lic": "Lancaster",
      "ll": 3,
      "lim": 0,
      "x": "This weapon deals 10AP energy to objects, cover, terrain, and the environment.\n\nPlasma cutters were tools first: simple blades built to toggle and sustain a plasma sheath, making it easier to cut metal. Repeated ad hoc use of cutters as personal defense weapons against pirate boarding parties convinced IPS-N of the need for a mil-spec variant of the civilian tool – the Cutter, now in its second generation. The Cutter MkII feeds directly from the mech’s power core, with a port to attach power packs in case of cord severance. Although the cutting edge can be shortened to a knife length, its most popular setting is the “cutlass”, a medium-length option perfect for balancing reach and maneuverability in close quarters."
