      "tr": "Ближний бой",
      "dr": "2d6 кинетический",
      "rr": "Дальность 3, Угроза 3",
      "xr": "Автоматический дробовик «Чистильщик палуб» — дробовик с ленточным питанием, любимец пилотов морской пехоты на станциях и крупных кораблях. Его методика проста: заряжай, целься, стреляй. Сужение одинарного ствола обеспечивает пневматическое поглощение отдачи — смягчая эффект его невероятной отдачи, — а ленточный податчик совместим со многими типами дроби и пуль.",
      "gr": "Неточное",
      "labr": "IPS-N · Тортуга · LL1 · Main",
      "lic": "Tortuga",
      "ll": 1,
      "lim": 0,
      "x": "The Deck-Sweeper Automatic Shotgun is a belt-fed scattergun, a favorite of marine pilots aboard stations and capital ships. Its methodology is straightforward: charge, point, and fire. A single-barrel constriction allows for pneumatic absorption – dampening the effect of its incredible recoil – and its belt feeder is compatible with many types of shot-and-slug ammunition."
