      "nr": "Гвоздемёт «Пронзатель»",
      "tr": "Ближний бой",
      "dr": "1d6+1 кинетический",
      "rr": "Дальность 5, Угроза 3",
      "xr": "При попадании: цели должны преуспеть в спасброске корпуса, иначе станут Обездвиженными до конца своего следующего хода.\n\nНегорючие двухступенчатые макрофлешетты «Пронзателя» в поддоне-сабо пробивают даже самую тяжёлую броню. Вылетев из установки, поддон отделяется на подлёте к цели и запускает вторую ступень — внутренний двигатель разгоняет макрофлешетту до невероятной скорости. Против мягких целей сквозное пробитие гарантировано; IPS-N советует стрелять из этого оружия, только когда область за целью свободна от союзников и некомбатантов.",
      "gr": "Тепло 1 (себе)",
      "labr": "IPS-N · Влад · LL2 · Main",
      "lic": "Vlad",
      "ll": 2,
      "lim": 0,
      "x": "On hit: {\"detail\": \"Targets must succeed on a Hull save or become Immobilized until the end of their next turn.\", \"add_status\": [{\"id\": \"immobilized\", \"duration\": \"next_turn_end_target\", \"save\": \"hull\"}]}\n\nThe Impaler’s noncombustible, sabot-jacketed two-stage macroflechettes can pierce even the heaviest armor. Once catapulted from its launcher, the sabot disengages on approach to its target and triggers a second stage – internal propulsion drives the macroflechette forward with incredible velocity. Over-penetration is certain against soft targets; IPS-N advises firing this weapon only when the area behind the target is clear of allies or noncombatants."
