      "xr": "Атакуя персонажа, который Лежит, Обездвижен или Оглушён, тег «Перебор» этого оружия при каждом срабатывании наносит дополнительно +1d6 бонусного урона. Это может срабатывать бесконечно, если на новом бонусном кубе выпадает 1, снова запуская «Перебор».\n\nБоевой бур — жестокое оружие ближнего боя, питаемое массивным внешним каталитическим блоком. Наконечник бура оснащён микроплазменными излучателями, предназначенными для предварительной обработки цели и обеспечения проникновения бура.",
