      "xr": "При попадании: все персонажи в поражённой области должны преуспеть в спасброске корпуса, иначе будут притянуты на 1d3+1 клетки к вам или как можно ближе.\n\nМагнитная пушка SSC — первая разработка Группы экзотических материалов: сфокусированный через апертуру электромагнитный проекционный луч, использующий мощные импульсы магнитной энергии для нарушения работы и повреждения оборудования. Цели, попавшие в луч магнитной пушки, получают дополнительный урон программному обеспечению, так как на чувствительные компоненты обрушивается огромный системный стресс.",
