      "xr": "Рельсотроны — простое, изящное оружие. С магнитно ускоренными снарядами и без движущихся частей они эффективны в любых условиях и полностью автономны в одноразовых блоках. Эта эффективность имеет цену: рельсотроны потребляют огромную мощность, поэтому их владельцам приходится носить вспомогательные блоки преобразования энергии, заряженные от ядра.",
