      "nr": "Разрывная установка",
      "tr": "Пусковая установка",
      "dr": "1d3 взрывной + 1 тепло",
      "rr": "Дальность 15",
      "xr": "При крите: цель становится Ослабленной до конца своего следующего хода.\n\n«Да, они могли умереть. Мы убили многих из них — разнесли их разрывными установками и пушками. Не думаю, что они что-то для него значили. Не как насекомые; не так… насекомые всё же нужны: как пища, как необходимые части экосистемы. Их смерти замедлили нас, но оно не приказывало им нас замедлять. Даже когда мы вскрыли последнюю камеру и увидели его, не думаю, что оно вообще заметило, что мы там.»",
      "gr": "Точное, Дуговое",
      "labr": "SSC · Сумеречное Крыло · LL2 · Main",
      "lic": "Dusk Wing",
      "ll": 2,
      "lim": 0,
      "x": "On crit: {\"detail\": \"Target becomes Impaired until the end of their next turn.\", \"add_status\": [{\"id\": \"impaired\", \"duration\": \"next_turn_end_target\"}]}\n\n“Yes, they could die. We killed many of them – blew them away with burst launchers and cannons. I don’t think they mattered to it. Not like insects; not like that… there’s still a use for insects: as food, as necessary components in an ecosystem. Their deaths slowed us, but it didn’t command them to slow us. Even when we breached the last chamber and saw it, I don’t even think it recognized we were there.”"
