      "dr": "1d6+1 кинетический",
      "rr": "Линия 10",
      "xr": "Рельсовые винтовки — популярное оружие для любых условий, но единственный выбор для пилотов, действующих в атмосферах из легковоспламеняющихся газов. Они используют ряд каскадных электромагнитов, разгоняющих малые снаряды до огромных скоростей, и стреляют без сгорания.\nКак и другое рельсовое оружие, рельсовые винтовки тише своих традиционных собратьев, хотя огромные потребности в энергии затрудняют маскировку их энергетической сигнатуры.",
