      "dr": "3 взрывной",
      "rr": "Дальность 15",
      "xr": "Это оружие может атаковать две цели одновременно.\n\n«Это была дуэль. Ради этого их и создали: чтобы сражаться на дуэли и в этом бою сотрясти столпы вселенной». — «Заметки для юного Джона», «Наставления Учителя»",
