      "tr": "Пусковая установка",
      "dr": "1d6+3 энергетический",
      "rr": "Дальность 15",
      "xr": "SP: 1\n\nРакеты «Гандива» — надёжная основа линейки BELLA CIAO от Smith-Shimano. Как и более тяжёлая «Пинака», «Гандива» оснащена системами реактивного перепозиционирования в полёте, улучшающими наведение на цель в быстро меняющейся обстановке боя. Платформой доставки «Гандивы» управляет роевой ИИ дрона COMP/CON, что даёт ей способность учиться на каждом запуске.",
      "gr": "Точное, Самонаводящееся, Умное",
      "labr": "SSC · Монарх · LL2 · Heavy",
      "lic": "Monarch",
      "ll": 2,
      "lim": 0,
      "x": "SP: 1\n\nGandiva missiles are a reliable mainstay from Smith-Shimano’s BELLA CIAO line. Like the heavier Pinaka, the Gandiva is equipped with jet-assisted midflight repositioning systems, enhancing target navigation in rapidly changing battlefield environments. The Gandiva’s delivery platform is administered by a hivemind COMP/CON drone AI, giving it the capacity to learn from each right-of-launch experience."
