      "xr": "Вы получаете реакцию «Хруп-хруп» — это единственный способ атаковать этим оружием.\n\nХруп-хруп (реакция — 1/раунд): Триггер: враждебный персонаж в пределах дальности вопальной пушки и в линии видимости наносит урон союзному персонажу.\nВы можете совершить атаку по враждебному персонажу из вопальной пушки.\n\nНЕ СМОТРИТЕ ПРЯМО В АПЕРТУРУ.",
