      "dr": "1d3+2 переменный",
      "rr": "Дальность 10",
      "xr": "При атаке: выберите тип урона этого оружия.\n\nНексусы «Гуль» командуют одними из крупнейших боеспособных дронов в современном бою. Эти дроны чуть меньше среднего человека — металлические цилиндры, ощетинившиеся узлами подвески, подходящими для большинства пехотных противотанковых средств. Приводимые в движение реактивными системами вертикального взлёта и зависания, дроны «Гуль» — грозные автономные машины для любых условий, которые трудно отследить и сбить.",
