      "dr": "1d6+3 энергетический",
      "rr": "Вспышка 2",
      "xr": "При атаке: в начале вашего следующего хода вы можете совершить вторую атаку этим оружием протоколом. Эта вторичная атака не может наносить бонусный урон и не вызывает дополнительных вторичных атак.\nВы можете центрировать атаку этого оружия на себе или на любом из ваших дронов в пределах сенсоров.\n\nВторичная атака нексуса «Аннигиляция» (протокол): если на прошлом ходу вы атаковали нексусом «Аннигиляция», вы можете совершить вторую атаку этим оружием. Эта вторичная атака не может наносить бонусный урон и не вызывает дополнительных вторичных атак.\nВы можете центрировать атаку этого оружия на себе или на любом из ваших дронов в пределах сенсоров.\n\n«Шторм клинковой смерти» — наниты, организованные в манипулы и выпускаемые из бортовых нексусов шасси или одноразовых пусковых труб залпом нитевых колец, настолько острых, что они срезают цели на молекулярном уровне. Визуальный эффект запуска манипулы часто сравнивают с мишурой, выстреливаемой сквозь атмосферу.",
      "gr": "Бронебойное (AP), Умное",
