      "lic": "Hydra",
      "ll": 3,
      "lim": 0,
      "x": "On attack: You can make a second attack with this weapon at the start of your next turn as a protocol. This secondary attack can’t deal bonus damage, and doesn't trigger additional secondary attacks.\nYou may center this weapon’s attack on either yourself or any of your Drones within Sensors.\n\nAnnihilation Nexus Secondary Attack (Protocol): If you made an attack with the Annihilation Nexus on your last turn, you can make a second attack with this weapon. This secondary attack can’t deal bonus damage, and doesn't trigger additional secondary attacks.\nYou may center this weapon’s attack on either yourself or any of your Drones within Sensors.\n\n“A storm of bladed death” – nanites organized into maniples, released from a chassis’ onboard nexuses or single-use firing tubes in a burst of filament rings so sharp they slice away at their targets on the molecular level. The visual effect of a maniple being launched is often compared to tinsel being fired through atmosphere."
