      "rr": "Дальность 5",
      "xr": "При попадании: вы также можете совершить вторичную атаку по другому персонажу в пределах дальности 3 от первой цели. Вы можете продолжать совершать вторичные атаки при попаданиях, пока есть новые подходящие цели в пределах дальности; однако каждая атака даёт 1 тепло, а вторичные атаки не могут наносить бонусный урон. Персонажа нельзя поразить более одного раза одним выстрелом этого оружия.\n\n«Да падёт на тебя огонь, АПЕП! Плоть твоя будет сожжена с костей твоих; Владыка Дуата никогда не позволит твоей тени восстать вновь!»",
