      "nr": "Умная винтовка",
      "tr": "Винтовка",
      "dr": "4 кинетический",
      "rr": "Дальность 15",
      "xr": "SP: 2\n\n«Умное оружие» — широкий термин, описывающий любое оружие, способное взаимодействовать с бортовыми системами для повышения боевой эффективности. Умные винтовки — это оружие, заранее оснащённое сопутствующим ПО и необходимым оборудованием для взаимодействия с системами наведения и принимающими NHP. Популярное дополнение ко многим мехам HORUS, умное оружие — надёжная система кинетической доставки.",
