      "nr": "Пушка-мимик",
      "tr": "???",
      "dr": "??? кинетический",
      "rr": "Дальность ???",
      "xr": "У этого ужасающего оружия нет базовой формы; оно постоянно искажается, принимая разные обличья и подражая оружию других бойцов. Оно одновременно считается всеми типами дальнобойного оружия (например, ближний бой, винтовка и т.д.), но не может принимать моды и получать бонусы ядра, хотя от талантов получает пользу как обычно.\nВ начале боя бросьте 3d20 и запишите результаты по порядку: X, Y и Z. X — это его начальная базовая дальность (до модификаторов от талантов). В начале каждого вашего хода после первого пушка-мимик переключается на следующий результат, принимая его как базовую дальность. После Z она возвращается к X.\nПушка-мимик наносит кинетический урон, равный 1 + половина её текущей базовой дальности.\nВы можете спровоцировать пушку-мимика полным действием, бросив новый набор 3d20.\n\nСпровоцировать пушку-мимика (полное): бросьте новый набор 3d20, чтобы задать значения пушки-мимика.\n\nЭто не пушка.",
      "gr": "",
      "labr": "HORUS · Пегас · LL2 · Heavy",
      "lic": "Pegasus",
      "ll": 2,
      "lim": 0,
      "x": "This horrifying weapon has no basic form; it constantly contorts itself into different shapes, mimicking the weapons of other combatants. It counts as all ranged weapon types simultaneously (e.g., CQB, Rifle, etc.), but it can’t take Mods or benefit from core bonuses, although it still benefits from talents as normal.\nAt the start of combat, roll 3d20 and note the results in order: X, Y, and Z. X is its starting base Range (before modifications from talents). At the start of each of your turns after the first, the mimic gun cycles to the next result, taking that as its base Range. After Z, it cycles back to X.\nThe mimic gun does kinetic equal to 1 + half of its current base Range.\nYou may provoke the mimic gun as a full action, rolling a new set of 3d20.\n\nProvoke Mimic Gun (Full): Roll a new set of 3d20 to set the Mimic Gun's values.\n\nThis is not a gun."
