      "dr": "3d6 взрывной",
      "rr": "Дальность 30, Взрыв 2",
      "xr": "Профиль — Осадный режим: 3d6 взрывной; Дальность 30, Взрыв 2; теги: Дуговое, Тяжёлое орудие, Перезаряжаемое, Тепло 4 (себе)\n\nПрофиль — Режим прямой наводки: 3d6 взрывной; Дальность 20; теги: Отброс 2, Тепло 2 (себе)\n\nОсадная пушка — квинтэссенция артиллерии Арсенала: пушка-гаубица с автоматизированной системой заряжания. Обычно устанавливается на дальнобойные мехи в ролях артиллерии или поддержки отряда; осадные пушки способны вести как навесной, так и прямой огонь по необходимости, с различными вариантами боеприпасов.",
      "gr": "",
      "labr": "HA · Барбаросса · LL3 · Superheavy",
      "lic": "Barbarossa",
      "ll": 3,
      "lim": 0,
      "x": "Profile — Siege Mode: 3d6 Explosive; Range 30, Blast 2; tags: Arcing, Ordnance, Loading, Heat 4 (Self)\n\nProfile — Direct Fire Mode: 3d6 Explosive; Range 20; tags: Knockback 2, Heat 2 (Self)\n\nThe siege cannon is the Armory’s quintessential artillery piece: a howitzer cannon fed by an automated loading system. Typically mounted on long-range mechs deployed in artillery or squad-support roles, siege cannons are capable of both indirect and direct fire as the situation demands with variable ammunition options."
