      "dr": "1d6+2 энергетический + 6 ожог",
      "rr": "Конус 7, Линия 10",
      "xr": "Можно выстрелить как конус 7 или линия 10.\n\nПри атаке: белое пламя продолжает гореть в 3 свободных клетках по вашему выбору в поражённой области до конца сцены. Когда персонажи начинают свой ход в одной из этих клеток или впервые за раунд входят в неё, они получают 1d6 энергетического урона.\n\nПлазменный огнемёт появился слишком поздно в Герцинийском кризисе, чтобы получить широкое применение в поле. Скудные данные, собранные у эскадрилий МЭС, которые его использовали, говорят о том, что плазменные огнемёты могли бы оказать огромное влияние на исходы нескольких крупных сражений самой кровопролитной фазы кризиса.",
      "gr": "Тепло 4 (себе)",
