      "lab": "HA · Iskander · LL2 · Heavy",
      "sf": "Harrison Armory",
      "nr": "Гравитационная пушка",
      "tr": "Винтовка",
      "dr": "",
      "rr": "Дальность 8, Взрыв 3",
      "xr": "При атаке: персонажи в поражённой области должны преуспеть в спасброске корпуса, иначе получат 1d6 энергетического урона и будут притянуты как можно ближе к центру взрыва. Это оружие нельзя модифицировать, и оно не получает бонусов ядра.\n\n«Сложные переговоры гравитации и времени, разрушенные в одно мгновение машиной, способной щипать волны, как музыкант щиплет струны гитары.\nМы поставили на службу оружие силу, что держит всё в своих объятиях. Что может пойти не так?»",
