      "lab": "HA · Sherman · LL1 · Main",
      "sf": "Harrison Armory",
      "nr": "Лазерная винтовка «SOL»",
      "tr": "Винтовка",
      "dr": "1d6 энергетический + 1 ожог",
      "rr": "Дальность 8",
      "xr": "Лазерные винтовки содержат ряд апертур и линз, усиливающих и фокусирующих свет в узкие лучи, иногда видимые, которые нагревают зону попадания достаточно долго, чтобы превратить её в плазму. Лазерная винтовка образца SOL стабильно выдаёт 3,5 петаватт в импульсном режиме, но может также испускать непрерывный луч на меньшей мощности. SOL полностью автономна, но может подключаться к реакторному ядру меха для экстренной перезарядки.\nХотя некоторые лазерные винтовки служат также устройствами связи и передачи данных, SOL строго предназначена для боевых применений.",
      "gr": "Тепло 1 (себе)",
      "labr": "HA · Шерман · LL1 · Main",
      "lic": "Sherman",
      "ll": 1,
      "lim": 0,
      "x": "Laser rifles contain a series of apertures and lenses that amplify and focus light into tight beams, sometimes visible, that heat the zone of impact for long enough to turn it into plasma. The SOL-Pattern Laser Rifle consistently outputs 3.5 petawatts, pulsed, but can also project a steady beam at lower power levels. The SOL is entirely self-contained but can be patched into a mech’s reactor core for emergency recharge.\nAlthough some laser rifles double as communications and data-transfer devices, the SOL is strictly suitable for combat applications."
