      "dr": "1d3+2 энергетический",
      "rr": "Дальность 5, Угроза 3",
      "xr": "При попадании: совершите вторичную атаку по всем персонажам в пределах вспышки 1 от цели. Эти атаки не могут наносить бонусный урон и не вызывают затрат тепла или вторичных атак «Аннигилятора».\n\nHarrison Armory известна несколько нетрадиционными методами разработки: тактические решения так же часто придумываются и проектируются в поле, как и в лаборатории, причём первые часто превосходят вторые. Название «Аннигилятор» происходит из сленга пилотов — так называли кустарно собранное оружие, впервые импровизированное во время восстания Брэдбери, когда отчаявшиеся пилоты сопротивления нашли способ направлять невероятное отработанное тепло своих реакторов в направленный выброс.",
      "gr": "Бронебойное (AP), Тепло 2 (себе)",
      "labr": "HA · Токугава · LL1 · Main",
      "lic": "Tokugawa",
      "ll": 1,
      "lim": 0,
      "x": "On hit: Make a secondary attack against all characters within burst 1 of the target. These attacks can’t deal bonus damage, and don’t trigger the Annihilator’s heat cost or secondary attacks.\n\nHarrison Armory is known to employ somewhat unconventional development methods: tactical solutions are theorized and designed in the field as often as they are in the lab, with the former often outperforming the latter. The Annihilator’s name comes from pilots’ slang for a jury-rigged weapon first improvised in the Bradbury Rebellion, when desperate resistance pilots found a way to shunt the incredible waste heat from their reactors into a directed blast."
