      "xr": "Профиль — 1 заряд: 1d6 энергетический; Линия 4; профиль этого оружия определяется числом зарядов, которые оно несёт. Оно начинает с 1 заряда, нанося 1d6 энергетического урона линией 4. Каждый раз, когда вы проводите стабилизацию, вы получаете дополнительный 1 заряд, максимум до 4. ZF4 получает дополнительно +4 к линии и +1d6 энергетического урона за каждый заряд и сбрасывается до 1 заряда после каждой атаки. Заряды сохраняются между сценами, но теряются при полном ремонте.\n\nПрофиль — 2 заряда: 2d6 энергетический; Линия 8; профиль этого оружия определяется числом зарядов, которые оно несёт. Оно начинает с 1 заряда, нанося 1d6 энергетического урона линией 4. Каждый раз, когда вы проводите стабилизацию, вы получаете дополнительный 1 заряд, максимум до 4. ZF4 получает дополнительно +4 к линии и +1d6 энергетического урона за каждый заряд и сбрасывается до 1 заряда после каждой атаки. Заряды сохраняются между сценами, но теряются при полном ремонте.\n\nПрофиль — 3 заряда: 3d6 энергетический; Линия 12; профиль этого оружия определяется числом зарядов, которые оно несёт. Оно начинает с 1 заряда, нанося 1d6 энергетического урона линией 4. Каждый раз, когда вы проводите стабилизацию, вы получаете дополнительный 1 заряд, максимум до 4. ZF4 получает дополнительно +4 к линии и +1d6 энергетического урона за каждый заряд и сбрасывается до 1 заряда после каждой атаки. Заряды сохраняются между сценами, но теряются при полном ремонте.\n\nПрофиль — 4 заряда: 4d6 энергетический; Линия 16; профиль этого оружия определяется числом зарядов, которые оно несёт. Оно начинает с 1 заряда, нанося 1d6 энергетического урона линией 4. Каждый раз, когда вы проводите стабилизацию, вы получаете дополнительный 1 заряд, максимум до 4. ZF4 получает дополнительно +4 к линии и +1d6 энергетического урона за каждый заряд и сбрасывается до 1 заряда после каждой атаки. Заряды сохраняются между сценами, но теряются при полном ремонте.",
      "gr": "Тяжёлое орудие",
      "labr": "Main",
      "lic": "",
      "ll": null,
      "lim": 0,
      "x": "Profile — 1 Charge: 1d6 Energy; Line 4; This weapon’s profile is determined by the number of Charges it carries. It begins with 1 Charge, dealing 1d6 energy with line 4. Each time you Stabilize, you gain an additional 1 Charge, up to a maximum of 4. The ZF4 gains an additional +4 line and +1d6 energy damage for each charge, and resets to 1 Charge after each attack. Charges persist between scenes, but are lost during a full repair.\n\nProfile — 2 Charges: 2d6 Energy; Line 8; This weapon’s profile is determined by the number of Charges it carries. It begins with 1 Charge, dealing 1d6 energy with line 4. Each time you Stabilize, you gain an additional 1 Charge, up to a maximum of 4. The ZF4 gains an additional +4 line and +1d6 energy damage for each charge, and resets to 1 Charge after each attack. Charges persist between scenes, but are lost during a full repair.\n\nProfile — 3 Charges: 3d6 Energy; Line 12; This weapon’s profile is determined by the number of Charges it carries. It begins with 1 Charge, dealing 1d6 energy with line 4. Each time you Stabilize, you gain an additional 1 Charge, up to a maximum of 4. The ZF4 gains an additional +4 line and +1d6 energy damage for each charge, and resets to 1 Charge after each attack. Charges persist between scenes, but are lost during a full repair.\n\nProfile — 4 Charges: 4d6 Energy; Line 16; This weapon’s profile is determined by the number of Charges it carries. It begins with 1 Charge, dealing 1d6 energy with line 4. Each time you Stabilize, you gain an additional 1 Charge, up to a maximum of 4. The ZF4 gains an additional +4 line and +1d6 energy damage for each charge, and resets to 1 Charge after each attack. Charges persist between scenes, but are lost during a full repair."
