      "tr": "",
      "xr": "Когда вы получаете урон структуре, бросьте 1к6. При выпадении 6 вы возвращаетесь к 1 HP и игнорируете урон — попадание просто «поцарапало краску».\nЭту систему можно использовать только один раз до каждого полного ремонта, и она не является допустимой целью для уничтожения системы.",
