      "nr": "Развёртываемое укрытие «Иерихон» образца А",
      "tr": "Развёртываемое",
      "xr": "Разверните две секции прочного укрытия размера 1 в свободных пространствах, соседних с вами и друг с другом. Каждая секция — объект с уклонением 5 и 10 HP, который можно нацелить и уничтожить отдельно. Обе секции укрытия можно снова подобрать полным действием.\nРемонт системы восстанавливает обе секции.\n\nРазвёртываемое укрытие «Иерихон» образца А (развёртываемое, размер 1, HP 10, уклонение 5): разверните две секции прочного укрытия размера 1 в свободных пространствах, соседних с вами и друг с другом. Каждая секция — объект с уклонением 5 и 10 HP, который можно нацелить и уничтожить отдельно. Обе секции укрытия можно снова подобрать полным действием.\nРемонт системы восстанавливает обе секции.",
