      "n": "Turret Drones",
      "t": "Drone",
      "p": 2,
      "lab": "GMS · LL0 · 2 SP",
      "sf": "",
      "nr": "Дроны-турели",
      "tr": "Дрон",
      "xr": "Потратьте заряд, чтобы развернуть дрон-турель, который крепится к любому объекту или поверхности в пределах сенсоров и линии видимости. Получите реакцию «Атака турели», которую можно использовать один раз за каждую развёрнутую дрон-турель. Дроны-турели нельзя отозвать, они истекают в конце сцены.\n\nДрон-турель (дрон, размер 0,5, HP 5, уклонение 10, E-Defense 10): получите реакцию «Атака турели», которую можно использовать один раз за каждую развёрнутую дрон-турель. Дроны-турели нельзя отозвать, они истекают в конце сцены.\n\nИспользование дронов-турелей — довольно традиционная форма умножения силы, которая остаётся основой обороны на многих театрах военных действий.",
      "labr": "GMS · LL0 · 2 SP",
      "lic": "GMS",
      "ll": 0,
      "lim": 3,
      "x": "Expend a charge to deploy a turret drone that attaches to any object or surface within Sensors and line of sight. Gain the Turret Attack reaction, which can be taken once for each deployed turret drone. Turret drones cannot be recalled and expire at the end of the scene.\n\nTurret Drone (Drone, Size 0.5, HP 5, Evasion 10, E-Defense 10): Gain the Turret Attack reaction, which can be taken once for each deployed turret drone. Turret drones cannot be recalled and expire at the end of the scene.\n\nThe use of turret drones is a rather traditional form of force multiplication – one that has remained the backbone of defense in many theaters.",
