      "xr": "Проецируемый щит (протокол): назначьте персонажа в пределах линии видимости: все дальние или рукопашные атаки, которые он совершает против вас или которые вы совершаете против него, получают +2 к сложности до начала вашего следующего хода.\n\nПроецируемый щит GMS «Тип-3» ловит и отражает входящие снаряды, проецируя агрессивный суперпозиционный антибаллистический барьер.",
