      "nr": "Проектор мерцающего поля",
      "tr": "",
      "xr": "Каждый раз, когда вы ускоряетесь или совершаете обычное перемещение, вы проецируете вокруг себя голографический узор, оставляя ослепительные послесвечения, из-за которых трудно определить ваше точное местоположение: до следующей атаки по вам вы считаетесь невидимым. Одновременно может действовать только один такой эффект.\n\n«Я видел себя снова, и снова, и снова, и снова, и снова, и снова, и снова, и—»",
