      "nr": "Оглушающая корона",
      "tr": "",
      "xr": "(Быстрое действие): потратьте заряд, чтобы создать вспышку света 3. Все враждебные персонажи в зоне поражения, имеющие линию видимости до вас, должны преуспеть в спасброске ловкости, иначе станут заглушенными, и в спасброске систем, иначе станут ослабленными. Эти эффекты длятся до конца их следующего хода.\nПерсонажи, находящиеся в укрытии от вас, не затрагиваются этой системой.\n\n„Многое произошло в тот момент, когда, как мне кажется, я умер“.",
