      "nr": "Активный камуфляж",
      "tr": "",
      "xr": "(Протокол): Вы становитесь невидимым, пока не получите урон или до конца своего следующего хода.\n\nАктивный камуфляж — вершина контр-оптических систем защиты. Системы активного камуфляжа непрерывно интерпретируют поступающие данные видимого света, позволяя им проецировать светопреломляющие поля вокруг своего пользователя и эффективно скрывать его на виду у всех.",
