      "t": "Tech",
      "p": 2,
      "lab": "SSC · Mourning Cloak · LL2 · 2 SP",
      "sf": "Smith-Shimano",
      "nr": "Комплекс охотничьей логики",
      "tr": "Тех",
      "xr": "Выследить добычу (вторжение): вы заражаете цель вирусным кодом, который стирает ваш образ с её сенсоров. Она считает вас невидимым, пока не получит от вас урон. Одновременно может действовать только на одну цель.\n\nУстрашить (вторжение): вы заражаете цель вирусным кодом, из-за которого ваш мех кажется ей ужасающим. До конца её следующего хода она становится ослабленной и не может совершать добровольные перемещения, приближающие её к вам.\n\nСозданная из интерпретированных нитей паракода DHIYED, «Охотничья логика» SSC — это гибкая вычислительная меметика: двойное синтетическое/VLS-векторное системное оружие, способное вмешиваться как в компьютер цели, так и в её экипаж.",
      "labr": "SSC · Траурница · LL2 · 2 SP",
      "lic": "Mourning Cloak",
      "ll": 2,
      "lim": 0,
      "x": "Stalk Prey (Invade): You infect the target with a viral logic that wipes your image from their sensors. They treat you as Invisible until you next take damage from them. This can only affect one target at a time.\n\nTerrify (Invade): You infect the target with a viral logic that makes your mech appear horrifying. Until the end of their next turn, they become Impaired and cannot make any voluntary movements that bring them closer to you.\n\nBuilt from interpreted strands of DHIYED paracode, SSC’s Hunter Logic is an agile computational memetic: a dual synthetic/VLS-vector systemic weapon capable of interfering with both a target’s computer and its crew.",
