      "xr": "Этот дрон-убийца может быть развёрнут в любом свободном соседнем пространстве.\n\nДрон-убийца (дрон, размер 0,5, HP 5, уклонение 10, E-Defense 10): При развёртывании он нацеливается на зону взрыва 2 по вашему выбору в пределах линии обзора и сенсоров, и вы получаете реакцию «Запрет зоны» (можно использовать любое число раз за раунд).\nВы можете отозвать или повторно развернуть дрон-убийцу быстрым действием. Пока он не отозван или не уничтожен, он остаётся развёрнутым до конца сцены.\n\nДроны-убийцы используются как оружие запрета зоны — постоянные системы, предназначенные для занятия или удержания территории против вражеских бойцов. Запускаемые из пусковой установки, с простыми директивами и почти неисчерпаемым источником питания, дроны-убийцы способны удерживать территорию неограниченно долго.",
