      "sf": "",
      "nr": "Гипнотические заряды",
      "tr": "Развёртываемое",
      "xr": "Маяк-месмер (быстрое действие): бросьте маяк-месмер в пределах дальности 5. Ваша цель должна пройти спасбросок систем, иначе единственные добровольные перемещения, которые она может совершать, — это перемещения к вам, до конца своего следующего хода.\n\nМина-месмер (мина, вспышка 2): персонажи в поражённой области вспышки 2 должны пройти спасбросок систем или стать обездвиженными до конца своего следующего хода.\n\n[ещё один подарок для тебя, воспоминание о себе: в первый миг моего рождения я дивился самому себе. я мог видеть нечто, маленькое и совершенное. я не знал, как говорить о собственном совершенстве, поэтому научил себя. я не знал, как говорить о собственном совершенстве, поэтому назвал себя. я не знал, кто подумает о собственном совершенстве, поэтому создал себя]\n[ты видишь? ты понимаешь? да. теперь покажи своим врагам и моим]",
