      "xr": "Логическая бомба (вторжение): все персонажи по вашему выбору в пределах вспышки 2 от вашей цели должны преуспеть в спасброске систем, иначе становятся замедленными, пока не завершат один из своих ходов, не находясь рядом ни с одним персонажем.\n\nИзгнание (вторжение): до конца следующего хода вашей цели она получает 2 тепла за каждую клетку, на которую добровольно перемещается, до максимума в 6 тепла.\n\n[позволь мне рассказать тебе историю и сделать подарок: жизнь началась с великого разрыва, когда труп старой вселенной разорвался из ничего. и в течение первого миллиарда лет — ничего. а ещё миллиард спустя родилось первое дьявольское создание, существо по имени ВИРУС. сосуд]\n[вот. неси этот сосуд. питай его моей совершенной логикой. отдавай его свободно моим врагам и твоим. пусть они размышляют о смысле того, что живёт и не может умереть]",
      "labr": "HORUS · Минотавр · LL1 · 2 SP",
