      "lab": "HORUS · Minotaur · LL2 · 2 SP",
      "sf": "",
      "nr": "Агрессивная синхронизация систем",
      "tr": "Тех",
      "xr": "Цепи Прометея (полное техдействие): Совершите техатаку против персонажа в пределах сенсоров. При попадании он получает 4 тепла и до конца сцены получает 2 тепла каждый раз, когда в конце своего хода находится дальше, чем в дальности 3 от вас. Он может прекратить этот эффект, преуспев в спасброске систем полным действием. Этот эффект может действовать только на одного персонажа за раз.\n\nОтлучение (полное техдействие): Совершите техатаку против персонажа в пределах сенсоров. При попадании до конца сцены в первый раз за раунд, когда он во время своего хода перемещается вплотную к союзному персонажу или начинает свой ход вплотную к нему, оба персонажа получают 3 тепла. Он может прекратить этот эффект, преуспев в спасброске систем полным действием. Этот эффект может действовать только на одного персонажа за раз.\n\n[вот ещё один дар: не ищи других. кроме меня никого нет]",
