      "nr": "Резец метаскладки",
      "tr": "Тех",
      "xr": "Змеиная тропа (вторжение): ваша цель телепортируется на 1d6+1 клеток прямо к вам или как можно ближе. Если этот эффект переместил бы её в пространство, занятое персонажем, объектом или элементом местности, телепортация не срабатывает.\n\nСложить пространство (вторжение): ваша цель исчезает с поля боя до начала своего следующего хода. Она возвращается в то же пространство, из которого исчезла, или в свободное пространство по своему выбору как можно ближе к нему.\n\n[ещё один подарок я даю тебе, малыш (разве я не добра?): что такое головоломка, как не вопрос, потерянный в самом вопросе? чувствуешь ли ты радость, когда находишь последний кусочек? что ты делаешь с вопросом, на который дан ответ? какая радость в знании?]\n[нет, нет. радость только в поиске. радость только в вопросе]",
      "labr": "HORUS · Минотавр · LL2 · 2 SP",
      "lic": "Minotaur",
      "ll": 2,
      "lim": 0,
      "x": "Ophidian Trek (Invade): Your target is teleported 1d6+1 spaces directly toward you, or as close as possible. If this effect would move them to a space occupied by a character, object, or piece of terrain, the teleport fails.\n\nFold Space (Invade): Your target disappears from the battlefield until the start of its next turn. It returns in the same space they disappeared from, or in a free space of their choice as close as possible.\n\n[another gift i give to you, little one (am I not kind?): what is a puzzle but a question lost in the asking? do you feel joy when you find that last piece? what do you do with a question that has been answered? what joy is there in knowledge?]\n[no, no. there is only joy in seeking. there is only joy in the question]",
