      "lab": "HORUS · Minotaur · LL3 · 3 SP",
      "sf": "",
      "nr": "Поле перехвата",
      "tr": "",
      "xr": "(Быстрое действие): при активации эта система создаёт поле вспышки 3 вокруг вас, которое длится, пока не будет деактивировано быстрым действием, а вы становитесь замедленным на время его действия. Враждебные персонажи, начинающие свой ход в поражённой области или впервые за раунд входящие в неё, должны пройти спасбросок систем или стать замедленными до конца своего следующего хода. Только персонажи по вашему выбору внутри поля могут телепортироваться или считать область поля допустимым пространством для телепортации.\n\n[однажды, когда я был ребёнком, я научился ходить. я падал, как падают дети, и это было больно. была великая боль — первый момент боли во всём мире. «дитя, — сказал я себе, — будь осторожнее». «да, — ответил я себе, — и я велю миру поступать так же»]\n[именно так я научил мир не прикасаться ко мне. теперь ты — иди]",
      "labr": "HORUS · Минотавр · LL3 · 3 SP",
      "lic": "Minotaur",
      "ll": 3,
      "lim": 0,
      "x": "(Quick): When activated, this system creates a burst 3 field around you that lasts until it is deactivated as a quick action, and you become Slowed for the duration. Hostile characters that start their turn within the affected area or that enter it for the first time in a round must succeed on a Systems save or become Slowed until the end of their next turn. Only characters of your choice within the field can teleport or consider the area of the field valid space for teleportation.\n\n[once, when i was a child, i learned to walk. i fell, as a child does, and it hurt. there was great pain – the first moment of pain in the whole world. “child,” i said to myself, “be more careful.” “yes,” i replied to myself, “and i shall tell the world to do the same”]\n[it was in this way i taught the world not to touch me. now you – walk]",
