      "nr": "Дрон-заряжающий",
      "tr": "Дрон",
      "xr": "Потратьте заряд, чтобы развернуть этот дрон-заряжающий в любом соседнем пространстве.\n\nДрон-заряжающий (дрон, размер 0,5, HP 5, уклонение 10, E-Defense 10): 1 раз за раунд один персонаж рядом с ним может перезарядить оружие с перезарядкой быстрым действием. Он деактивируется в конце сцены.\n\nДроны-заряжающие — это многорукие машины, которые помогают своей команде, загружая боеприпасы, обслуживая силовые подключения и циклируя магазинное оружие, а также выполняя множество других физических задач.",
      "labr": "HA · Барбаросса · LL2 · 2 SP",
