      "lim": 1,
      "x": "Expend a charge to deploy this autoloader drone to any adjacent space.\n\nAutoloader Drone (Drone, Size 0.5, HP 5, Evasion 10, E-Defense 10): 1/round, one character adjacent to it may reload a Loading weapon as a quick action. It deactivates at the end of the scene.\n\nAutoloader drones are many-limbed machines that assist their team by loading ordnance, maintaining powerline hookups, and cycling magazine-fed weapons, in addition to many other physical tasks.",
