      "lab": "HA · Barbarossa · LL2 · 2 SP",
      "sf": "Harrison Armory",
      "nr": "Зенитная установка",
      "tr": "",
      "xr": "(Быстрое действие): Выберите летающего персонажа в пределах дальности 15 и линии обзора. Он должен преуспеть в спасброске ловкости, иначе немедленно приземлится (это считается падением без урона), а также станет замедленным и не сможет летать до конца своего следующего хода.\n\nРазработанные для использования против атмосферных летунов, эти зенитные автопушки стреляют простыми снарядами с контактным или неконтактным взрывателем, эффективными против лёгкой брони, органических и субалтернных целей.",
      "labr": "HA · Барбаросса · LL2 · 2 SP",
