      "xr": "(Быстрое действие — 1/раунд): 1 раз за раунд вы можете активировать эту систему, чтобы перезарядить оружие с перезарядкой.\n\nВнешняя подача боеприпасов — это любые боеприпасы сверх того, что находится во встроенном хранилище меха: от магазинов, пристёгнутых к корпусу или конечностям; аккумуляторных блоков, прикреплённых к набедренным застёжкам; или массивных спинных блоков боеприпасов и зарядов — внешние системы гарантируют, что у пилотов более чем достаточно мощи, чтобы довести дело до конца.",
