      "x": "Flash Lock (Reaction — 1/round): Trigger: You or an allied character in Sensors and line of sight is pushed, pulled, knocked back or knocked Prone.\nTake 2 Heat. The movement or status is prevented, and the target gains Immunity to all the above effects until the start of their next turn.\n\nFlash anchors utilize user-directed quantum superpositional lockdown projection to identify and assist allies in physical combat and rapid movement, maintaining positionality in all circumstances.",
