      "xr": "Ваш мех получает тег ИИ.\nВы разработали собственного NHP. Этот NHP может говорить с вами и обладает личностью, но он менее развит, чем большинство NHP, и неспособен к независимому мышлению, полагаясь на ваши указания. Действуя в одиночку, он будет следовать последнему данному указанию и защищаться по мере необходимости; однако у него ограниченная инициатива, и он не получает пользы от ваших талантов.\n\n[нетерпеливый ученик].\nПолучено от таланта пилота «Технофил»: ранг I.",
