      "tr": "",
      "xr": "1 раз за ход, когда вы атакуете основным дальнобойным оружием, вы можете потратить заряды, чтобы применить к вашей атаке один из следующих эффектов по указанной цене.\n\n• ГРОХОТ: атака получает ОТБРОС 1 и наносит взрывной урон.\n• ШОК: атака наносит энергетический урон. Выберите одного персонажа, по которому направлена ваша атака; соседние персонажи получают 1 бронебойного энергетического урона, независимо от того, было попадание или промах.\n• МАГ: атака получает ДУГОВОЕ и наносит кинетический урон.\n• АДСКИЙ ОГОНЬ (2 заряда): атака наносит энергетический урон, а любой бонусный урон наносится как ожог.\n• ЕГЕРЬ (2 заряда): атака получает ОТБРОС 2, наносит взрывной урон, и один персонаж, по которому попала атака — по вашему выбору — должен преуспеть в спасброске корпуса или быть сбитым с ног.\n• САБО (2 заряда): атака получает БРОНЕБОЙНОСТЬ и наносит кинетический урон.\n\nПолучено от таланта пилота «Ходячий арсенал»: ранг II.",
      "labr": "GMS · LL0 · 0 SP",
      "lic": "GMS",
      "ll": 0,
      "lim": 6,
      "x": "1/turn, when you attack with a Main ranged weapon, you may expend charges to apply one of the following effects to your attack at the listed cost.\n\n• THUMPER: The attack gains KNOCKBACK 1 and deals Explosive damage.\n• SHOCK: The attack deals Energy damage. Choose one character targeted by your attack; adjacent characters take 1 AP Energy Damage, whether the result is a hit or miss.\n• MAG: The attack gains ARCING and deals Kinetic damage.\n• HELLFIRE (2 charges): The attack deals Energy damage and deals any bonus damage as Burn.\n• JAGER (2 charges): The attack gains KNOCKBACK 2, deals Explosive damage, and one character hit by the attack – your choice – must succeed on a HULL save or be knocked PRONE.\n• SABOT (2 charges): The attack gains AP and deals Kinetic damage.\n\nGained from the Walking Armory: Rank II pilot talent.",
