      "tr": "",
      "xr": "1 раз за ход, когда вы атакуете основным дальнобойным оружием, вы можете потратить заряды, чтобы применить к вашей атаке один из следующих эффектов по указанной цене.\n\n• ГРОХОТ: атака получает ОТБРОС 1 и наносит взрывной урон.\n• ШОК: атака наносит энергетический урон. Выберите одного персонажа, по которому направлена ваша атака; соседние персонажи получают 1 бронебойного энергетического урона, независимо от того, было попадание или промах.\n• МАГ: атака получает ДУГОВОЕ и наносит кинетический урон.\n• АДСКИЙ ОГОНЬ (2 заряда): атака наносит энергетический урон, а любой бонусный урон наносится как ожог.\n• ЕГЕРЬ (2 заряда): атака получает ОТБРОС 2, наносит взрывной урон, и один персонаж, по которому попала атака — по вашему выбору — должен преуспеть в спасброске корпуса или быть сбитым с ног.\n• САБО (2 заряда): атака получает БРОНЕБОЙНОСТЬ и наносит кинетический урон.\n\nЕсли вы совершаете критическое попадание, используя боеприпасы из вашего ящика боеприпасов, вы не тратите заряды. Если у вашей атаки больше одной цели, этот эффект применяется только к первому броску атаки, который вы совершаете.\n\nПолучено от таланта пилота «Ходячий арсенал»: ранг III.",
